import os
from moler.device import DeviceFactory


def get_fpga_upgrade_script_files(build_path, device=None, file_name="RFSW.txz"):
    """
    Generate needed files for upgrade fpga scripts and returns dictionary with paths to files

    :param build_path: path to downloaded RFSW package
    :param device: moler device where package is stored
    :param file_name: name of RFSW package
    :return: {
              "ASIHUB2.0": {
                "gen1": {
                  "image": "/tmp/RFSW_ASIHUB2/lib/firmware/ant/squatch1/squatch.fbf",
                  "image_md5": "/tmp/RFSW_ASIHUB2/lib/firmware/ant/squatch1/image_md5"
                },
                "gen2": {
                  "image": "/tmp/RFSW_ASIHUB2/lib/firmware/ant/squatch2/Squatch2.bin",
                  "image_md5": "/tmp/RFSW_ASIHUB2/lib/firmware/ant/squatch2/image_md5"
                },
                "gen3": {
                  "image": "/tmp/RFSW_ASIHUB2/lib/firmware/ant/squatch3/Squatch3.bin",
                  "image_md5": "/tmp/RFSW_ASIHUB2/lib/firmware/ant/squatch3/image_md5"
                }
              },
              "ASIHUB": {
                "gen1": {
                  "image": "/tmp/RFSW_ASIHUB/lib/firmware/ant/squatch1/squatch.fbf",
                  "image_md5": "/tmp/RFSW_ASIHUB/lib/firmware/ant/squatch1/image_md5"
                },
                "gen2": {
                  "image": "/tmp/RFSW_ASIHUB/lib/firmware/ant/squatch2/Squatch2.bin",
                  "image_md5": "/tmp/RFSW_ASIHUB/lib/firmware/ant/squatch2/image_md5"
                },
                "gen3": {
                  "image": "/tmp/RFSW_ASIHUB/lib/firmware/ant/squatch3/Squatch3.bin",
                  "image_md5": "/tmp/RFSW_ASIHUB/lib/firmware/ant/squatch3/image_md5"
                }
              }
            }
    """
    device = DeviceFactory.get_device(name='UnixLocal') if device is None else device
    fpga_images = get_fpga_images_from_rfsw_build(device, build_path, file_name)
    for version in fpga_images.values():
        version_paths = version["image"].split("/")
        version_path = "/".join(version_paths[:-1])
        build_name = version_paths[-1]
        version["image_md5"] = generate_image_md5_file(device, build_name, version_path)
    return fpga_images


def get_fpga_images_from_rfsw_build(device, build_path, file_name="RFSW.txz"):
    directory_name = file_name.split(".")[0]
    directory_path = os.path.join(build_path, directory_name)
    device.get_cmd(cmd_name="mkdir", cmd_params={"path": directory_path, "options": "-p"})()
    device.get_cmd(cmd_name="tar", cmd_params={"options": "-xvf ", "file": os.path.join(build_path, file_name)
                                               + " -C  {}".format(directory_path)})()
    return {
        "gen1": find_fpga_images_in_rfsw_build(device, directory_path, "squatch.fbf"),
        "gen2": find_fpga_images_in_rfsw_build(device, directory_path, "Squatch2.bin"),
        "gen3": find_fpga_images_in_rfsw_build(device, directory_path, "Squatch3.bin")
    }


def find_fpga_images_in_rfsw_build(device, build_path, image_name):
    find_path = device.get_cmd(cmd_name="find", cmd_params={"options": "{} -name '{}'"
                               .format(build_path, image_name)})()["RESULT"][0]

    return {"image": find_path, "image_md5": find_path.replace(image_name, "metainfo")}


def generate_image_md5_file(device, image_name, path, image_md5_file_name="image_md5"):
    image_md5_path = os.path.join(path, image_md5_file_name)
    with open(os.path.join(path, "metainfo"), "r") as f:
        image_md5 = f.read().strip().split("\n")[-1]
    device.get_cmd(cmd_name="echo", cmd_params={"options": "-e", "text": "{}\n{}".format(image_name, image_md5),
                                                "output_file": image_md5_path})()
    return image_md5_path
